CREATE TYPE "public"."payment_kind" AS ENUM ('card', 'cash');
CREATE TABLE "payment" ( "id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "kind" public.payment_kind NOT NULL, "order_id" integer NOT NULL, "amount" decimal NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "uq-payment-id-kind" UNIQUE ("id", "kind") );
CREATE TABLE "card_payment" ( "payment_id" integer NOT NULL, "last_four" text NOT NULL, "kind" public.payment_kind GENERATED ALWAYS AS ('card') STORED, PRIMARY KEY ("payment_id"), CONSTRAINT "fk-card_payment-payment_id-kind" FOREIGN KEY ("payment_id", "kind") REFERENCES "payment" ("id", "kind") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE );
ALTER TABLE "payment" ADD COLUMN "card_id" integer GENERATED ALWAYS AS ((CASE WHEN ("kind" = 'card') THEN "id" END)) STORED, ADD CONSTRAINT "fk-payment-card_id" FOREIGN KEY ("card_id") REFERENCES "card_payment" ("payment_id") DEFERRABLE INITIALLY IMMEDIATE;
